const items = $input.all();

// Función para validar y mantener el formato de fecha DD/MM/YYYY HH:mm
function formatearFecha(fechaString) {
  if (!fechaString) return '';

  try {
    // Si la fecha ya está en formato DD/MM/YYYY HH:mm, la devolvemos tal cual
    const formatoEsperado = /^\d{1,2}\/\d{1,2}\/\d{4}\s\d{1,2}:\d{1,2}$/;
    if (formatoEsperado.test(fechaString)) {
      return fechaString;
    }

    // Si está en otro formato (como RFC 2822), intentamos convertirla
    const fecha = new Date(fechaString);

    // Verificamos si la fecha es válida
    if (isNaN(fecha.getTime())) {
      return fechaString; // Si no es válida, devolvemos el string original
    }

    const dia = fecha.getDate();
    const mes = fecha.getMonth() + 1;
    const anio = fecha.getFullYear();
    const horas = fecha.getHours().toString().padStart(2, '0');
    const minutos = fecha.getMinutes().toString().padStart(2, '0');

    return `${dia}/${mes}/${anio} ${horas}:${minutos}`;
  } catch (error) {
    return fechaString;
  }
}

// Función para limpiar el prefijo "whatsapp:"
function limpiarNumero(numero) {
  if (!numero) return '';
  return numero.replace('whatsapp:', '');
}

// Mapeamos cada item de entrada y extraemos solo los campos necesarios
const mensajesProcesados = items.map(item => {
  const mensaje = item.json;

  return {
    json: {
      body: mensaje.body || '',
      account_sid: mensaje.account_sid || '',
      date_sent: formatearFecha(mensaje.date_sent),
      date_updated: formatearFecha(mensaje.date_updated),
      from: limpiarNumero(mensaje.from),
      to: limpiarNumero(mensaje.to)
    }
  };
});

return mensajesProcesados;

