// Obtener la fecha de hoy (solo día, mes y año)
const hoy = new Date();
const diaHoy = hoy.getDate();
const mesHoy = hoy.getMonth() + 1;
const anioHoy = hoy.getFullYear();
// Filtrar solo los mensajes de hoy
const mensajesDeHoy = items.filter(item => {
  const mensaje = item.json;
  // Extraer la fecha del campo date_sent (formato: "8/10/2025 13:42")
  if (!mensaje.date_sent) return false;
  const partes = mensaje.date_sent.split(' ')[0].split('/');
  const dia = parseInt(partes[0]);
  const mes = parseInt(partes[1]);
  const anio = parseInt(partes[2]);
  // Comparar si es del día de hoy
  return dia === diaHoy && mes === mesHoy && anio === anioHoy;
});
return mensajesDeHoy;

