  const partes = mensaje.date_sent.split(' ')[0].split('/');
  const dia = parseInt(partes[0]);
  const mes = parseInt(partes[1]);
  const anio = parseInt(partes[2]);
  // Comparar si es del día de hoy
  return dia === diaHoy && mes === mesHoy && anio === anioHoy;
});
